// @ts-check
import { createReadStream, existsSync } from "node:fs";
import { defineConfig } from "astro/config";
import type { PluginOption } from "vite-plus";

// PDFs are generated by `astro build`; serve the last built copies during dev.
const servePdfsFromDist: PluginOption = {
  name: "syr-serve-built-pdfs",
  configureServer(server) {
    server.middlewares.use((request, response, next) => {
      const match = /^\/(cv-david-malmstrom-(?:en|sv)\.pdf)$/.exec(request.url ?? "");
      const file = match && new URL(`./dist/${match[1]}`, import.meta.url);
      if (!file || !existsSync(file)) return next();
      response.setHeader("Content-Type", "application/pdf");
      createReadStream(file).pipe(response);
    });
  },
};

export default defineConfig({
  i18n: {
    locales: ["en", "sv"],
    defaultLocale: "en",
    routing: {
      prefixDefaultLocale: false,
    },
  },
  vite: { plugins: [servePdfsFromDist] },
});
